  muted:   "8FA8C8",
  text:    "D6E4F7",
  light:   "F5F8FF",
  teal:    "2DD4BF",
  red:     "EF4444",
  green:   "22C55E",
  slate:   "94A3B8",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.25 });

