const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Auditing Model Substitution in LLM APIs";
pres.author = "ML Security Research";

// === COLOR PALETTE: Midnight Executive ===
// Dark navy dominant, ice blue accent, white text, coral for warnings
const C = {
  navy:    "0F1F3D",   // dominant dark bg
  navy2:   "152848",   // slightly lighter navy
  navy3:   "1C3460",   // card/panel bg
  ice:     "8FB4D9",   // ice blue accent
  coral:   "E05C4B",   // warning/highlight
  gold:    "F0B429",   // data highlight
  white:   "FFFFFF",
  offWhite:"EEF2F8",
  muted:   "8FA8C8",
  text:    "D6E4F7",
  light:   "F5F8FF",
  teal:    "2DD4BF",
  red:     "EF4444",
  green:   "22C55E",
  slate:   "94A3B8",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.25 });

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 1: Title Slide
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.06, h: 5.625,
    fill: { color: C.coral }, line: { color: C.coral }
  });

  // Top geometric accent
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.06, y: 0, w: 10, h: 0.04,
    fill: { color: C.ice, transparency: 50 }, line: { color: C.ice, transparency: 50 }
  });

  // Background circuit-pattern shapes
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.2, y: 0.3, w: 2.5, h: 2.5,
    fill: { color: C.navy3, transparency: 30 },
    line: { color: C.ice, width: 0.5, transparency: 60 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.8, y: 0.9, w: 1.9, h: 1.9,
    fill: { color: C.navy2, transparency: 20 },
    line: { color: C.teal, width: 0.5, transparency: 50 }
  });

  // Eyebrow label
  slide.addText("SECURITY RESEARCH  ·  ARXIV 2504.04715", {
    x: 0.4, y: 1.1, w: 6, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: C.ice,
    charSpacing: 3, bold: false
  });

  // Main title
  slide.addText("Are You Getting\nWhat You Pay For?", {
    x: 0.4, y: 1.55, w: 8.5, h: 1.6,
    fontSize: 40, fontFace: "Georgia", color: C.white,
    bold: true, lineSpacingMultiple: 1.15
  });

  // Subtitle
  slide.addText("Auditing Model Substitution in LLM APIs:\nWhy Software Tests Fail and Hardware Attestation Wins", {
    x: 0.4, y: 3.25, w: 8.5, h: 0.85,
    fontSize: 15, fontFace: "Calibri", color: C.ice,
    lineSpacingMultiple: 1.3
  });

  // Tagline box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.2, w: 7.8, h: 0.7,
    fill: { color: C.navy3 },
    line: { color: C.coral, width: 1.5 }
  });
  slide.addText("Commercial LLM providers have strong economic incentives to covertly substitute cheaper models — and today's detection methods cannot stop them.", {
    x: 0.55, y: 4.25, w: 7.5, h: 0.6,
    fontSize: 11, fontFace: "Calibri", color: C.text, italic: true,
    valign: "middle"
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 2: The Substitution Problem
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };

  // Header bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 1.0,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.06, h: 5.625,
    fill: { color: C.coral }, line: { color: C.coral }
  });

  slide.addText("THE MODEL SUBSTITUTION PROBLEM", {
    x: 0.35, y: 0.0, w: 9, h: 1.0,
    fontSize: 10, fontFace: "Calibri", color: C.ice,
    charSpacing: 2, bold: true, valign: "middle"
  });

