    x: 0, y: 0, w: 0.06, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Label
  slide.addText("THE SOLUTION: HARDWARE ATTESTATION", {
    x: 0.35, y: 0.2, w: 9, h: 0.38,
    fontSize: 10, fontFace: "Calibri", color: C.teal,
    charSpacing: 2, bold: true
  });

  slide.addText("Trusted Execution Environments Provide Provable Cryptographic Model Integrity", {
    x: 0.35, y: 0.65, w: 9.3, h: 0.65,
    fontSize: 20, fontFace: "Georgia", color: C.white, bold: true
  });

  slide.addText("TEEs are hardware-secured enclaves that provide cryptographic attestation of code and data being executed.", {
    x: 0.35, y: 1.38, w: 9.3, h: 0.38,
    fontSize: 12, fontFace: "Calibri", color: C.muted
  });

  // How TEEs work - flow
  const steps = [
    { n: "1", title: "Model Weights Loaded", desc: "Correct weights loaded into hardware-secured enclave" },
    { n: "2", title: "Inference Executed", desc: "Computation runs inside TEE; provider cannot tamper" },
    { n: "3", title: "Cryptographic Proof", desc: "Attestation report signed by hardware root of trust" },
    { n: "4", title: "Auditor Verifies", desc: "Client verifies proof without trusting the provider" },
  ];

  steps.forEach((s, i) => {
    const x = 0.25 + i * 2.4;
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: 1.92, w: 2.2, h: 1.6,
      fill: { color: C.navy3 }, line: { color: C.teal, width: 1 },
      shadow: makeShadow()
    });
    slide.addShape(pres.shapes.OVAL, {
      x: x + 0.75, y: 1.98, w: 0.7, h: 0.7,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    slide.addText(s.n, {
      x: x + 0.75, y: 1.98, w: 0.7, h: 0.7,
      fontSize: 18, fontFace: "Georgia", color: C.navy,
      bold: true, align: "center", valign: "middle"
    });
    slide.addText(s.title, {
      x: x + 0.08, y: 2.76, w: 2.04, h: 0.38,
      fontSize: 10.5, fontFace: "Calibri", color: C.white,
      bold: true, align: "center"
    });
    slide.addText(s.desc, {
      x: x + 0.08, y: 3.15, w: 2.04, h: 0.35,
      fontSize: 9.5, fontFace: "Calibri", color: C.muted,
      align: "center"
    });
    // Arrow
    if (i < 3) {
      slide.addShape(pres.shapes.LINE, {
        x: x + 2.2, y: 2.72, w: 0.2, h: 0,
        line: { color: C.teal, width: 1.5 }
      });
    }
  });

  // Comparison: TEE vs ZKP vs Software
  const compRows = [
    ["Property", "Software Tests", "Zero-Knowledge Proofs", "TEEs (Recommended)"],
    ["Provability", "None — defeatable", "Provable in theory", "Provable in practice"],
    ["Computational Cost", "Low but query-heavy", "Prohibitive (huge models)", "Modest overhead"],
    ["Deployment Today", "Deployed but unreliable", "Not viable at scale", "✓ NVIDIA H100 / Confidential Compute"],
    ["Adversarial Robustness", "Defeated by design", "Depends on prover", "Hardware root of trust"],
  ];

  const teeH = (t, i) => ({
    text: t,
    options: {
      bold: true,
      color: i === 3 ? C.navy : C.white,
      fill: { color: i === 3 ? C.teal : (i === 0 ? C.navy3 : "2A3A5A") },
      align: "center", fontSize: 9.5
    }
  });
  const teeC = (t, col) => ({ text: t, options: { color: col || C.text, fontSize: 9.5, align: "center" } });

  const compData = compRows.map((row, ri) =>
    row.map((cell, ci) => {
      if (ri === 0) return teeH(cell, ci);
      if (ci === 0) return teeC(cell, C.ice);
      if (ci === 3) return teeC(cell, C.teal); // highlight TEE column
      if (ci === 1) return teeC(cell, C.coral);
      return teeC(cell, C.muted);
    })
  );

  slide.addTable(compData, {
    x: 0.25, y: 3.65, w: 9.5, h: 1.75,
    rowH: [0.3, 0.35, 0.35, 0.35, 0.35],
    colW: [1.8, 2.0, 2.4, 3.3],
    border: { pt: 0.5, color: "2A4A6A" },
    fill: { color: C.navy2 }
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 9: Key Takeaways
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.coral }, line: { color: C.coral }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.06, h: 5.625,
    fill: { color: C.coral }, line: { color: C.coral }
  });

  slide.addText("KEY TAKEAWAYS", {
    x: 0.35, y: 0.18, w: 9, h: 0.35,
    fontSize: 10, fontFace: "Calibri", color: C.coral,
    charSpacing: 3, bold: true
  });

  slide.addText("Close the Verification Gap with Hardware Attestation", {
    x: 0.35, y: 0.6, w: 9.3, h: 0.6,
    fontSize: 22, fontFace: "Georgia", color: C.white, bold: true
  });

  const findings = [
    {
      num: "01",
      title: "Economically Motivated & Practically Undetectable",
      body: "Covert model substitution reduces GPU costs while maintaining pricing. Black-box APIs provide no guarantee the advertised model is served.",
      accent: C.coral
    },
    {
      num: "02",
      title: "FP8 Quantization Barely Affects Benchmarks",
      body: "Scores fall within error bars on MMLU and GSM8K. Temperature scaling amplifies noise faster than signal — detection remains infeasible.",
      accent: C.gold
    },
    {
      num: "03",
      title: "Inference Nondeterminism Defeats Log-Prob Fingerprinting",
      body: "SW framework and GPU hardware variations (transformers, vLLM, A100 vs H100) produce different log-probs for the same model.",
      accent: C.ice
    },
    {
      num: "04",
      title: "Randomized Substitution Defeats Statistical Tests",
      body: "Mixed distribution with p → 0 requires exponentially more queries. Benchmark evasion makes audit passes trivially achievable.",
      accent: C.teal
    },
    {
      num: "05",
      title: "TEEs Are the Only Viable Path Today",
      body: "Hardware attestation via NVIDIA Confidential Compute (H100) provides provable model integrity with modest overhead — actionable now.",
      accent: C.green
    },
  ];

  findings.forEach((f, i) => {
    const col = i < 3 ? 0 : 1;
    const row = i < 3 ? i : i - 3;
    const x = 0.25 + col * 4.9;
    const y = 1.35 + row * 1.35;
    const w = 4.55;

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w, h: 1.22,
      fill: { color: C.navy3 }, line: { color: f.accent, width: 0.8 }
    });
    // Number badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 0.42, h: 1.22,
      fill: { color: f.accent }, line: { color: f.accent }
    });
    slide.addText(f.num, {
      x, y, w: 0.42, h: 1.22,
      fontSize: 13, fontFace: "Georgia", color: C.navy,
      bold: true, align: "center", valign: "middle"
    });
    slide.addText(f.title, {
      x: x + 0.5, y: y + 0.08, w: w - 0.6, h: 0.32,
      fontSize: 10.5, fontFace: "Calibri", color: f.accent,
      bold: true
    });
    slide.addText(f.body, {
      x: x + 0.5, y: y + 0.42, w: w - 0.6, h: 0.72,
      fontSize: 9.5, fontFace: "Calibri", color: C.text
    });
  });

  // CTA
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.25, y: 5.1, w: 9.5, h: 0.42,
    fill: { color: C.coral }, line: { color: C.coral }
  });
  slide.addText("Community Call to Action: Demand TEE-backed attestation from LLM API providers. Treat unverified inference as untrusted.  arxiv.org/abs/2504.04715", {
    x: 0.4, y: 5.12, w: 9.2, h: 0.38,
    fontSize: 10.5, fontFace: "Calibri", color: C.white,
    bold: true, align: "center", valign: "middle"
  });
}

// Save
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Saved: /app/output/final_deck.pptx"))
  .catch(e => { console.error(e); process.exit(1); });

