  navy2:   "152848",
  navy3:   "1C3460",
  ice:     "8FB4D9",
  coral:   "E05C4B",
  gold:    "F0B429",
  white:   "FFFFFF",
  text:    "D6E4F7",
  muted:   "8FA8C8",
  teal:    "2DD4BF",
  green:   "22C55E",
  slate:   "94A3B8",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.22 });

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 1: Title
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.07, h: 5.625,
    fill: { color: C.coral }, line: { color: C.coral }
  });

  // Eyebrow
  slide.addText("SECURITY RESEARCH  ·  ARXIV 2504.04715", {
    x: 0.4, y: 1.0, w: 9.2, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: C.ice,
    charSpacing: 3
  });

  // Main title
  slide.addText("Are You Getting\nWhat You Pay For?", {
    x: 0.4, y: 1.38, w: 7.8, h: 1.55,
    fontSize: 42, fontFace: "Georgia", color: C.white,
