    { num: "02", col: 1, row: 0, title: "FP8 Quantization Barely Affects Benchmarks", body: "Scores fall within error bars on MMLU and GSM8K. Temperature scaling amplifies noise faster than detection signal.", accent: C.gold },
    { num: "03", col: 0, row: 1, title: "Nondeterminism Defeats Log-Prob Fingerprinting", body: "SW framework and GPU hardware (transformers, vLLM, A100 vs H100) produce different log-probs for the same model.", accent: C.ice },
