const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Auditing Model Substitution in LLM APIs";
pres.author = "ML Security Research";

// Slide dimensions: 10" x 5.625"
// Safe margins: left/right 0.3", top 0.3", bottom 0.3" (0.06" accent bars excluded)

const C = {
  navy:    "0F1F3D",
  navy2:   "152848",
  navy3:   "1C3460",
  ice:     "8FB4D9",
  coral:   "E05C4B",
  gold:    "F0B429",
  white:   "FFFFFF",
  text:    "D6E4F7",
  muted:   "8FA8C8",
  teal:    "2DD4BF",
  green:   "22C55E",
  slate:   "94A3B8",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.22 });

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 1: Title
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.07, h: 5.625,
    fill: { color: C.coral }, line: { color: C.coral }
  });

  // Eyebrow
  slide.addText("SECURITY RESEARCH  ·  ARXIV 2504.04715", {
    x: 0.4, y: 1.0, w: 9.2, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: C.ice,
    charSpacing: 3
  });

  // Main title
  slide.addText("Are You Getting\nWhat You Pay For?", {
    x: 0.4, y: 1.38, w: 7.8, h: 1.55,
    fontSize: 42, fontFace: "Georgia", color: C.white,
    bold: true, lineSpacingMultiple: 1.1
  });

  // Subtitle
  slide.addText("Auditing Model Substitution in LLM APIs:\nWhy Software Tests Fail and Hardware Attestation Wins", {
    x: 0.4, y: 3.05, w: 8.8, h: 0.8,
    fontSize: 15, fontFace: "Calibri", color: C.ice,
    lineSpacingMultiple: 1.35
  });

  // Tagline box — leave 0.4" bottom margin
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.98, w: 9.2, h: 0.88,
    fill: { color: C.navy3 }, line: { color: C.coral, width: 1.5 }
  });
  slide.addText("Commercial LLM providers have strong economic incentives to covertly substitute cheaper models — and today's detection methods cannot stop them.", {
    x: 0.6, y: 4.03, w: 8.8, h: 0.78,
    fontSize: 11.5, fontFace: "Calibri", color: C.text,
    italic: true, valign: "middle"
  });
  // Leave ~0.25" bottom margin (5.625 - 3.98 - 0.88 = 0.765" from bottom)
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 2: Substitution Problem
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: "F4F7FB" };

  // Header bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.82,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.07, h: 5.625,
    fill: { color: C.coral }, line: { color: C.coral }
  });
  slide.addText("THE MODEL SUBSTITUTION PROBLEM", {
    x: 0.35, y: 0, w: 9.3, h: 0.82,
    fontSize: 10, fontFace: "Calibri", color: C.ice,
    charSpacing: 2, bold: true, valign: "middle"
  });

  slide.addText("Economic Incentives Drive Covert Swaps", {
    x: 0.35, y: 0.92, w: 9.3, h: 0.47,
    fontSize: 22, fontFace: "Georgia", color: C.navy, bold: true
  });

  slide.addText("Providers charge for named models (e.g. Llama-3-70B, Qwen2-72B) but the black-box API gives users no guarantee the advertised model is actually served. Covert substitution reduces GPU costs while maintaining pricing.", {
    x: 0.35, y: 1.45, w: 9.3, h: 0.55,
    fontSize: 12, fontFace: "Calibri", color: "2C3E50"
  });

  // Hypothesis box spans full width
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 2.1, w: 9.3, h: 0.62,
    fill: { color: C.navy3 }, line: { color: C.ice, width: 0.5 }
  });
  slide.addText([
    { text: "Hypothesis Testing Framework: ", options: { bold: true, color: C.gold } },
    { text: "Can an auditor distinguish P_spec(y|x) from P_actual(y|x)?  (H₀: same model; H₁: substituted model)", options: { color: C.white } }
  ], {
    x: 0.55, y: 2.12, w: 8.9, h: 0.58,
    fontSize: 11, fontFace: "Calibri", valign: "middle"
  });

  // 4 substitution type cards — leave 0.3" bottom margin
  // Card height = 1.6"; y = 2.85; bottom = 2.85 + 1.6 = 4.45; slide h = 5.625; margin = 1.175"
  const types = [
    { icon: "↓", label: "Smaller Model",    desc: "e.g., 8B instead\nof 70B" },
    { icon: "≈", label: "Quantized Variant", desc: "FP8 / INT8 instead\nof FP16" },
    { icon: "✦", label: "Fine-Tuned Version", desc: "Updated or modified\nweights" },
    { icon: "≠", label: "Different Family",  desc: "Entirely different\narchitecture" },
  ];

  types.forEach((t, i) => {
    const x = 0.25 + i * 2.4;
    const y = 2.88;
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 2.22, h: 2.45,
      fill: { color: C.navy }, line: { color: C.ice, width: 0.5 },
      shadow: makeShadow()
    });
    // Icon circle
    slide.addShape(pres.shapes.OVAL, {
      x: x + 0.76, y: y + 0.22, w: 0.7, h: 0.7,
      fill: { color: C.coral }, line: { color: C.coral }
    });
    slide.addText(t.icon, {
      x: x + 0.76, y: y + 0.22, w: 0.7, h: 0.7,
      fontSize: 18, fontFace: "Calibri", color: C.white,
      align: "center", valign: "middle", bold: true
    });
    slide.addText(t.label, {
      x: x + 0.1, y: y + 1.08, w: 2.02, h: 0.42,
      fontSize: 11.5, fontFace: "Calibri", color: C.white,
      bold: true, align: "center"
    });
    slide.addText(t.desc, {
      x: x + 0.1, y: y + 1.54, w: 2.02, h: 0.65,
      fontSize: 10.5, fontFace: "Calibri", color: C.muted,
      align: "center"
    });
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 3: Benchmark Table
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: "F4F7FB" };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.82,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.07, h: 5.625,
    fill: { color: C.gold }, line: { color: C.gold }
  });
  slide.addText("FP8 QUANTIZATION BENCHMARK COMPARISON", {
    x: 0.35, y: 0, w: 9.3, h: 0.82,
    fontSize: 10, fontFace: "Calibri", color: C.gold,
    charSpacing: 2, bold: true, valign: "middle"
  });

  slide.addText("FP8 Quantization Preserves Most Accuracy — Making Substitution Hard to Detect", {
    x: 0.35, y: 0.92, w: 9.3, h: 0.46,
    fontSize: 19, fontFace: "Georgia", color: C.navy, bold: true
  });
  slide.addText("Performance drops are small, often within error bars — FP8 is an attractive near-undetectable cost-cutting measure.", {
    x: 0.35, y: 1.43, w: 9.3, h: 0.32,
    fontSize: 11.5, fontFace: "Calibri", color: "445566"
  });

  const hdr = (txt, span) => {
    const opts = { bold: true, color: C.white, fill: { color: C.navy3 }, align: "center", fontSize: 10.5, valign: "middle" };
    if (span) opts.colspan = span;
    return { text: txt, options: opts };
  };
  const sub = (txt) => ({ text: txt, options: { bold: true, color: C.navy, fill: { color: "CDDFF0" }, align: "center", fontSize: 9.5, valign: "middle" } });
  const orig = (txt) => ({ text: txt, options: { color: "1A2B45", align: "center", fontSize: 10, valign: "middle" } });
  const fp8g = (txt) => ({ text: txt, options: { color: "217A21", align: "center", fontSize: 10, valign: "middle" } });
  const fp8r = (txt) => ({ text: txt, options: { color: C.coral, align: "center", fontSize: 10, bold: true, valign: "middle" } });

  const tableData = [
    [ hdr("Model"), hdr("MMLU", 2), hdr("GSM8K", 2), hdr("MATH", 2), hdr("GPQA Diamond", 2) ],
    [ { text: "", options: { fill: { color: "E8EFF8" } } }, sub("FP16"), sub("FP8"), sub("FP16"), sub("FP8"), sub("FP16"), sub("FP8"), sub("FP16"), sub("FP8") ],
    [ { text: "Llama-3-8B-Instruct", options: { color: "1A2B45", fontSize: 10, valign: "middle" } }, orig("62.69"), fp8g("62.43"), orig("61.14"), fp8g("60.90"), orig("20.65"), fp8r("14.91"), orig("22.62"), fp8r("20.14") ],
    [ { text: "Llama-3-70B-Instruct", options: { color: "1A2B45", fontSize: 10, valign: "middle" } }, orig("78.05"), fp8g("77.88"), orig("88.06"), fp8g("87.35"), orig("35.69"), fp8g("35.75"), orig("29.60"), fp8g("33.12") ],
    [ { text: "Gemma-2-9b-it", options: { color: "1A2B45", fontSize: 10, valign: "middle" } }, orig("71.86"), fp8g("71.92"), orig("81.80"), fp8g("79.41"), orig("33.41"), fp8g("32.53"), orig("28.64"), fp8g("27.81") ],
    [ { text: "Qwen2-72B-Instruct", options: { color: "1A2B45", fontSize: 10, valign: "middle" } }, orig("82.18"), fp8g("81.98"), orig("86.72"), fp8g("86.82"), orig("37.39"), fp8g("37.67"), orig("29.93"), fp8g("31.08") ],
    [ { text: "Mistral-7B-Instruct-v0.3", options: { color: "1A2B45", fontSize: 10, valign: "middle" } }, orig("59.15"), fp8g("58.77"), orig("35.90"), fp8r("32.20"), orig("8.94"), fp8g("7.68"), orig("21.60"), fp8g("22.72") ],
  ];

  slide.addTable(tableData, {
    x: 0.2, y: 1.83, w: 9.6, h: 3.45,
    rowH: [0.4, 0.3, 0.45, 0.45, 0.45, 0.45, 0.45],
    colW: [2.6, 0.88, 0.88, 0.88, 0.88, 0.88, 0.88, 0.86, 0.86],
    border: { pt: 0.5, color: "B8CCE4" },
    fill: { color: "F8FAFE" }
  });

  slide.addText([
    { text: " Green ", options: { color: "217A21", bold: true } },
    { text: "= within/near error bars  ", options: { color: "555555" } },
    { text: " Red/Bold ", options: { color: C.coral, bold: true } },
    { text: "= notable drop  ", options: { color: "555555" } },
    { text: " FP8 scores often indistinguishable from FP16 → detection is near-impossible", options: { color: "333333", italic: true } },
  ], {
    x: 0.2, y: 5.33, w: 9.6, h: 0.22,
    fontSize: 9.5, fontFace: "Calibri", valign: "middle"
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 4: Temperature Scaling
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: "F4F7FB" };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.82,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.07, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText("TEMPERATURE SCALING EXPERIMENTS", {
    x: 0.35, y: 0, w: 9.3, h: 0.82,
    fontSize: 10, fontFace: "Calibri", color: C.teal,
    charSpacing: 2, bold: true, valign: "middle"
  });

  slide.addText("Higher Temperature Amplifies Performance Gaps but Increases Noise", {
    x: 0.35, y: 0.92, w: 9.3, h: 0.46,
    fontSize: 19, fontFace: "Georgia", color: C.navy, bold: true
  });

  // Image: take up left ~56% of available height space
  // Available height: 5.625 - 0.82 (header) - 0.46 (title) - 0.12 (gap) - 0.3 (bottom margin) = 3.915"
  // Use y=1.45, image height = 3.85, bottom = 5.3; right margin kept
  slide.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 0.3, y: 1.45, w: 5.7, h: 3.85
  });

  // Right cards: 3 cards in ~3.85" height
  const insights = [
    { head: "Temperature 0.2 – 1.0", body: "Models maintain expected performance; FP8 and FP16 scores remain close, signal is weak.", accent: C.teal },
    { head: "Temperature 2.0", body: "Performance degrades across all models. Gaps become noisy and unreliable for detection.", accent: C.gold },
    { head: "Key Implication", body: "Higher temperature amplifies noise faster than signal, making statistical tests even less reliable for auditing.", accent: C.coral },
  ];

  const cardH = 1.18;
  const cardGap = 0.075;
  insights.forEach((ins, i) => {
    const y = 1.45 + i * (cardH + cardGap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.25, y, w: 3.45, h: cardH,
      fill: { color: C.navy }, line: { color: ins.accent, width: 1 },
      shadow: makeShadow()
    });
    // Accent top strip
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.25, y, w: 3.45, h: 0.2,
      fill: { color: ins.accent }, line: { color: ins.accent }
    });
    slide.addText(ins.head, {
      x: 6.38, y: y + 0.24, w: 3.2, h: 0.28,
      fontSize: 11, fontFace: "Calibri", color: ins.accent, bold: true
    });
    slide.addText(ins.body, {
      x: 6.38, y: y + 0.55, w: 3.2, h: 0.58,
      fontSize: 10, fontFace: "Calibri", color: C.text
    });
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 5: Log-Prob Nondeterminism
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: "F4F7FB" };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.82,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.07, h: 5.625,
    fill: { color: C.coral }, line: { color: C.coral }
  });
  slide.addText("LOG-PROBABILITY FINGERPRINTING", {
    x: 0.35, y: 0, w: 9.3, h: 0.82,
    fontSize: 10, fontFace: "Calibri", color: C.coral,
    charSpacing: 2, bold: true, valign: "middle"
  });

  slide.addText("Log Probability Fingerprinting Fails Due to Inference Nondeterminism", {
    x: 0.35, y: 0.92, w: 9.3, h: 0.46,
    fontSize: 18, fontFace: "Georgia", color: C.navy, bold: true
  });

  // Left column: description + failure reasons
  slide.addText("The Idea:", {
    x: 0.35, y: 1.5, w: 4.45, h: 0.28,
