  slide.addText("Why It Fails: Production Nondeterminism", {
    x: 0.45, y: 2.4, w: 4.25, h: 0.32,
    fontSize: 10.5, fontFace: "Calibri", color: C.white, bold: true, valign: "middle"
  });

  const failReasons = [
    "SW framework: transformers 4.40 vs 4.50 → different log-probs",
    "Inference engine: vLLM 0.6.2 vs 0.8.2 → different log-probs",
    "GPU hardware: A100 vs H100 → different log-probs",
  ];
  failReasons.forEach((r, i) => {
    const y = 2.77 + i * 0.6;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.35, y, w: 4.45, h: 0.52,
      fill: { color: "FEF0EE" }, line: { color: "E8C0BA", width: 0.5 }
    });
    slide.addShape(pres.shapes.OVAL, {
      x: 0.44, y: y + 0.1, w: 0.32, h: 0.32,
      fill: { color: C.coral }, line: { color: C.coral }
    });
    slide.addText(String(i + 1), {
      x: 0.44, y: y + 0.1, w: 0.32, h: 0.32,
      fontSize: 9.5, fontFace: "Calibri", color: C.white,
      bold: true, align: "center", valign: "middle"
    });
    slide.addText(r, {
      x: 0.85, y: y + 0.06, w: 3.88, h: 0.4,
      fontSize: 10.5, fontFace: "Calibri", color: "3D1A16", valign: "middle"
    });
  });

  // Bottom verdict box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 4.6, w: 4.45, h: 0.72,
    fill: { color: C.navy }, line: { color: C.ice, width: 0.8 }
  });
  slide.addText("Result: An auditor cannot distinguish a legitimate model served on different infrastructure from an actual substitution.", {
    x: 0.5, y: 4.64, w: 4.2, h: 0.64,
    fontSize: 10.5, fontFace: "Calibri", color: C.ice,
    italic: true, valign: "middle"
  });

  // Right image
  slide.addImage({
    path: "/app/benchmark/assets/figure_5.jpg",
    x: 5.05, y: 1.45, w: 4.65, h: 3.87
  });
  slide.addText("Fig. 5: Log-prob variation across frameworks & hardware for Llama-3-8B", {
    x: 5.05, y: 5.36, w: 4.65, h: 0.2,
    fontSize: 8.5, fontFace: "Calibri", color: C.slate, italic: true, align: "center"
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SLIDE 6: Randomized Substitution
// ─────────────────────────────────────────────────────────────────────────────
{
  const slide = pres.addSlide();
  slide.background = { color: "F4F7FB" };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.82,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.07, h: 5.625,
    fill: { color: C.gold }, line: { color: C.gold }
  });
  slide.addText("ADVERSARIAL COUNTERMEASURES", {
    x: 0.35, y: 0, w: 9.3, h: 0.82,
    fontSize: 10, fontFace: "Calibri", color: C.gold,
    charSpacing: 2, bold: true, valign: "middle"
  });

  slide.addText("Randomized Routing at Low Rates Makes Statistical Detection Query-Prohibitive", {
    x: 0.35, y: 0.92, w: 9.3, h: 0.46,
    fontSize: 18, fontFace: "Georgia", color: C.navy, bold: true
  });

