    slide.addText(s.n, {
      x: x + 0.76, y: y + 0.14, w: 0.7, h: 0.7,
      fontSize: 18, fontFace: "Georgia", color: C.navy,
      bold: true, align: "center", valign: "middle"
    });
    slide.addText(s.title, {
      x: x + 0.08, y: y + 0.92, w: 2.06, h: 0.3,
      fontSize: 11, fontFace: "Calibri", color: C.white,
      bold: true, align: "center"
    });
    slide.addText(s.desc, {
      x: x + 0.08, y: y + 1.22, w: 2.06, h: 0.28,
      fontSize: 9.5, fontFace: "Calibri", color: C.muted,
      align: "center"
    });
    if (i < 3) {
      slide.addShape(pres.shapes.LINE, {
