    [ tC("Compute Cost", C.ice), tC("Low but query-heavy", C.muted), tC("Prohibitive for LLMs", C.coral), tC("Modest overhead", C.teal) ],
    [ tC("Deploy Today", C.ice), tC("Unreliable", C.coral), tC("Not viable at scale", C.coral), tC("✓ NVIDIA H100 / CC", C.teal) ],
    [ tC("Adversarial Robustness", C.ice), tC("Defeated by design", C.coral), tC("Depends on prover", C.muted), tC("Hardware root of trust", C.teal) ],
