  });

  // 5 cards in 2-column grid (3 left, 2 right + 1 full-width or 3+2 grid)
  // Layout: col 0 x=0.22 w=4.65; col 1 x=5.1 w=4.65; gap=0.23
  // 3 rows: row 0 y=1.12; row 1 y=2.34; row 2 y=3.56 (cards 1-2-3 left, 4-5 right shifted)
  // Actually: place 5 cards in a clean 2-col layout, card 5 spans full width or right col only
  // Better: 2+2 top, 1 full-width bottom
  const cardW = 4.65;
  const cardH = 1.05;
  const colX = [0.22, 5.13];
  const rowY = [1.12, 2.25, 3.38];

  const findings = [
    { num: "01", col: 0, row: 0, title: "Economically Motivated & Undetectable", body: "Covert substitution reduces GPU costs while maintaining pricing. Black-box APIs give users no guarantee the advertised model is served.", accent: C.coral },
    { num: "02", col: 1, row: 0, title: "FP8 Quantization Barely Affects Benchmarks", body: "Scores fall within error bars on MMLU and GSM8K. Temperature scaling amplifies noise faster than detection signal.", accent: C.gold },
    { num: "03", col: 0, row: 1, title: "Nondeterminism Defeats Log-Prob Fingerprinting", body: "SW framework and GPU hardware (transformers, vLLM, A100 vs H100) produce different log-probs for the same model.", accent: C.ice },
    { num: "04", col: 1, row: 1, title: "Randomized Routing Defeats Statistical Tests", body: "Mixed distribution with p → 0 requires exponentially more queries. Benchmark evasion makes audits trivially passable.", accent: C.teal },
    { num: "05", col: 0, row: 2, title: "TEEs Are the Only Viable Path Today", body: "NVIDIA Confidential Compute (H100) provides provable model integrity with modest overhead — actionable now.", accent: C.green },
  ];

  findings.forEach((f) => {
    const x = colX[f.col];
    const y = rowY[f.row];
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: cardW, h: cardH,
      fill: { color: C.navy3 }, line: { color: f.accent, width: 0.8 }
    });
    // Left number badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 0.44, h: cardH,
      fill: { color: f.accent }, line: { color: f.accent }
    });
    slide.addText(f.num, {
      x, y, w: 0.44, h: cardH,
      fontSize: 13, fontFace: "Georgia", color: C.navy,
      bold: true, align: "center", valign: "middle"
    });
    slide.addText(f.title, {
      x: x + 0.52, y: y + 0.07, w: cardW - 0.62, h: 0.3,
      fontSize: 10.5, fontFace: "Calibri", color: f.accent, bold: true
    });
    slide.addText(f.body, {
      x: x + 0.52, y: y + 0.4, w: cardW - 0.62, h: 0.62,
      fontSize: 9.5, fontFace: "Calibri", color: C.text
    });
  });

  // CTA — fits in remaining space: row 2 y ends at 3.38 + 1.05 = 4.43; CTA starts 4.53
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.22, y: 4.53, w: 9.56, h: 0.82,
    fill: { color: C.coral }, line: { color: C.coral }
